import java.io.Serializable;
import java.io.ObjectInputStream;
import java.io.IOException;
import java.util.concurrent.locks.ReentrantLock;
import java.util.concurrent.atomic.AtomicInteger;

public class SafeConcurrentTaskProcessor implements Serializable {
    private static final long serialVersionUID = 42L;

    // STATIC: Shared across all instances, initialized thread-safely by JVM classloader
    private static final String PROCESSOR_TYPE = "HIGH_THROUGHPUT";

    // FINAL: Safe publication guaranteed; reference cannot be reassigned
    private final String processorId;
    private final AtomicInteger processedCount;

    // VOLATILE: Guarantees visibility of state changes across threads without locking
    private volatile boolean active;

    // TRANSIENT: Excluded from serialization; locks cannot and should not be serialized
    private transient ReentrantLock executionLock;

    public SafeConcurrentTaskProcessor(String processorId) {
        this.processorId = processorId; // Safe publication guaranteed
        this.processedCount = new AtomicInteger(0);
        this.active = true;
        this.executionLock = new ReentrantLock();
    }

    public void process(Runnable task) {
        if (!active) {
            throw new IllegalStateException("Processor is inactive");
        }

        executionLock.lock();
        try {
            task.run();
            processedCount.incrementAndGet();
        } finally {
            executionLock.unlock();
        }
    }

    public void shutdown() {
        this.active = false; // Volatile write: immediately visible to all threads
    }

    // Custom deserialization to safely reconstruct transient concurrent primitives
    private void readObject(ObjectInputStream in) throws IOException, ClassNotFoundException {
        in.defaultReadObject();
        // Re-initialize transient lock post-serialization to avoid NullPointerException
        this.executionLock = new ReentrantLock();
    }
}
